<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetCodeVO;

trait SnippetCodeAccessor
{
    private SnippetCodeVO $_code;
    public function getCode(): string
    {
        return $this->_code->value();
    }
    public function code(): SnippetCodeVO
    {
        return $this->_code;
    }
    public function isCodeChanged(?self $original = null): bool
    {
        return !$this->_code->equals($original?->_code);
    }
    public function withCode(SnippetCodeVO|string $code): self
    {
        $copy = clone $this;
        $copy->_code = SnippetCodeVO::from($code);
        return $copy;
    }
}
